package com.careerorbit.service;
import com.careerorbit.ai.ChatGateway;import com.careerorbit.entity.*;import com.careerorbit.mapper.*;import com.careerorbit.security.CurrentUser;import com.careerorbit.storage.ObjectStorageService;import com.careerorbit.common.BusinessException;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ResumeAuthorizationTest {@Test void userCannotReadOrDownloadAnotherUsersResume(){var resumes=mock(ResumeMapper.class);var current=mock(CurrentUser.class);var mine=new UserEntity();mine.id=7L;when(current.require()).thenReturn(mine);var foreign=new ResumeEntity();foreign.id=3L;foreign.userId=99L;foreign.objectKey="resumes/99/secret.pdf";when(resumes.selectById(3L)).thenReturn(foreign);var tx=new TransactionTemplate(mock(PlatformTransactionManager.class));var service=new ResumeService(resumes,mock(ResumeDiagnosisMapper.class),current,mock(ObjectStorageService.class),mock(ChatGateway.class),new ObjectMapper(),tx);assertThatThrownBy(()->service.get(3L)).isInstanceOf(BusinessException.class).hasMessage("简历不存在");assertThatThrownBy(()->service.download(3L)).isInstanceOf(BusinessException.class);}}
